/**
 * The generator of the API layer: pure functions from an OpenAPI document to TypeScript text. It reads no file and
 * runs no program; the script `scripts/web-gen-api.ts` gives it the contract, formats the result and writes it.
 */
import { generateOperations, generateOperationTable } from "./operations";
import type { OpenApiDocument } from "./spec";
import { generateTypeFiles } from "./types";

export type { OpenApiDocument } from "./spec";

/** The text of the generated files by file name, before formatting and before the header. */
export function generateBodies(doc: OpenApiDocument): Record<string, string> {
  return {
    ...generateTypeFiles(doc),
    "operations.ts": generateOperations(doc),
    "operation-table.ts": generateOperationTable(doc),
  };
}

export const CONTRACT_PATH = "backend/internal/contract/openapi/openapi.json";
export const GENERATED_DIR = "apps/web/src/api/generated";
const HEADER_LINES = 4;

/** The header of a generated file: which contract it was made from, and a hash of the text below the header. */
export function renderFile(
  body: string,
  contractSha256: string,
  sha256: (text: string) => string,
): string {
  const header = [
    `// Generated by apps/web/src/api/generator from ${CONTRACT_PATH}. Do not edit by hand.`,
    "// Regenerate with `pnpm web:gen-api`; the checks fail when this file and the contract differ.",
    `// contract-sha256: ${contractSha256}`,
    `// body-sha256: ${sha256(body)}`,
  ];
  return `${header.join("\n")}\n\n${body}`;
}

export interface ParsedFile {
  readonly contractSha256: string;
  readonly bodySha256: string;
  readonly body: string;
}

/** Read a generated file back: the two hashes of its header and the text below it. `undefined` when it has no header. */
export function parseFile(text: string): ParsedFile | undefined {
  const lines = text.split("\n");
  const contract = /^\/\/ contract-sha256: ([0-9a-f]{64})$/.exec(lines[2] ?? "");
  const body = /^\/\/ body-sha256: ([0-9a-f]{64})$/.exec(lines[3] ?? "");
  if (!contract || !body || lines.length <= HEADER_LINES || lines[HEADER_LINES] !== "")
    return undefined;
  return {
    contractSha256: contract[1] as string,
    bodySha256: body[1] as string,
    body: lines.slice(HEADER_LINES + 1).join("\n"),
  };
}
